"""
Module for parsing Egen log files (.pcap).

This module provides the EgenLogsParser class, which is designed to analyze
network traffic captures generated by Egen, within a given pcap file.

:copyright: Nokia Networks
:author: Mateusz Potoniec
:maintainer: Mateusz Potoniec
:contact: mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.egen import EgenLogsParser

    pcap_file = "/path/to/your/egen_capture.pcap"
    parser = EgenLogsParser()

    # Count the action types in the pcap file
    action_counts = parser.count_action_types(log_file_path=pcap_file)

    # ... further action types processing and checks ...

    # The counter can be reset if needed
    parser.reset_action_types_count()
"""

from typing import List, Dict
from uuid import uuid4
from enum import Enum
from dataclasses import dataclass

from taf.analyzer.pcap import pcap


class ActionType(Enum):
    """Enumeration for eCPRI action types."""
    REQUEST = "0x00"
    REQUEST_WITH_FOLLOW_UP = "0x01"
    RESPONSE = "0x02"
    REMOTE_REQUEST_WITH_FOLLOW_UP = "0x04"
    FOLLOW_UP = "0x05"


@dataclass
class ActionTypeCounter:
    """Data class to hold action type details and its message count."""
    name: str
    messages_count: int = 0


class EgenLogsParser:
    def __init__(self) -> None:
        self._action_type_counters: Dict[ActionType, ActionTypeCounter] = {
            ActionType.REQUEST: ActionTypeCounter(name="Request"),
            ActionType.REQUEST_WITH_FOLLOW_UP: ActionTypeCounter(name="Request with Follow_Up"),
            ActionType.RESPONSE: ActionTypeCounter(name="Response"),
            ActionType.REMOTE_REQUEST_WITH_FOLLOW_UP: ActionTypeCounter(name="Remote request with Follow_Up"),
            ActionType.FOLLOW_UP: ActionTypeCounter(name="Follow_Up"),
        }

    @property
    def action_types(self) -> Dict[str, Dict[str, int | str]]:
        """Returns the counters in the original dictionary format for more common type in further operations."""
        return {
            counter.name: {"field_value": action_type.value, "messages_count": counter.messages_count}
            for action_type, counter in self._action_type_counters.items()
        }

    def reset_action_types_count(self) -> None:
        """
        Resets messages count for all action types to zero.
        """
        for counter in self._action_type_counters.values():
            counter.messages_count = 0

    def count_action_types(self, log_file_path: str, reset_count: bool = False) -> Dict[str, Dict[str, int]]:
        """
        Counts Egen action types in the provided pcap log file.

        :param log_file_path: Path to the pcap log file.
        :param reset_count: Whether to reset the action types count before counting (Default: False).

        :return: Dictionary with action types and their corresponding message counts.
        """

        if reset_count:
            self.reset_action_types_count()

        for packet in self._setup_pcp_verifier_and_get_packets(pcap_file=log_file_path, filters="ecpri"):
            try:
                packet_action_type = packet.get_field_value_by_name('ecpri.actiontype')[0]
                action_type_enum = ActionType(packet_action_type)
                self._action_type_counters[action_type_enum].messages_count += 1
            except (IndexError, KeyError, ValueError):
                continue
        return self.action_types

    @staticmethod
    def _setup_pcp_verifier_and_get_packets(pcap_file: str, filters: str) -> List[object]:
        """
        Setups pcp verifier and gets packets based on passed pcap_file and filters params.

        :param pcap_file: Path to pcap file.
        :param filters: Filters for awited packets.

        :return: List contained all awited packets got from file
        """

        pcap_verifier_id = f"pcap_verifier_{uuid4().hex}"
        pcap_verifier = pcap()
        pcap_verifier.setup(infile=pcap_file, display_filter=filters, alias=pcap_verifier_id)
        packets = pcap_verifier.get_packets(pcap_parser=pcap_verifier_id)

        del pcap_verifier
        del pcap_verifier_id
        return packets
